// Package locales embeds the ICU MessageFormat catalogs shared by the server and the clients
// (ADR-0009). Each file is locales/<BCP47>/<namespace>.json in the FormatJS JSON shape;
// en is the source locale, en-XA and ar-XB are pseudo-locales generated by tools/i18n.
// Only internal/i18n reads this package.
package locales

import "embed"

// FS holds every <locale>/<namespace>.json catalog file.
//
//go:embed */*.json
var FS embed.FS
